// Validação no servidor: a página também valida, mas a validação do navegador pode ser contornada.
const b = $json.body || {};
const limpar = (v) => String(v ?? '').replace(/\s+/g, ' ').trim();
const nome = limpar(b.nome).slice(0, 120);
const email = limpar(b.email).toLowerCase().slice(0, 160);
const curso = limpar(b.curso);
const duvida = String(b.duvida ?? '').trim().slice(0, 1000);
const CURSOS = ['Ciência da Computação', 'Sistemas de Informação', 'Engenharia de Software', 'Análise e Desenvolvimento de Sistemas', 'Outro'];

const erros = {};
if (nome.length < 3) erros.nome = 'Informe o nome completo (mínimo de 3 caracteres).';
if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) erros.email = 'E-mail em formato inválido.';
if (!CURSOS.includes(curso)) erros.curso = 'Curso inválido.';
if (duvida.length < 10) erros.duvida = 'A dúvida precisa ter pelo menos 10 caracteres.';

// Protocolo DV-AAAAMMDD-XXXX, sem caracteres ambíguos (O/0, I/1).
const agora = DateTime.now().setZone('America/Sao_Paulo');
const ALFA = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
let sufixo = '';
for (let i = 0; i < 4; i++) sufixo += ALFA[Math.floor(Math.random() * ALFA.length)];

return {
  json: {
    valido: Object.keys(erros).length === 0,
    erros,
    mensagem: 'Confira os campos destacados e envie novamente.',
    nome, email, curso, duvida,
    // Cópia da dúvida usada no prompt: chaves viram parênteses para não quebrar o template da IA.
    duvida_ia: duvida.replace(/[{}]/g, (c) => (c === '{' ? '(' : ')')),
    protocolo: `DV-${agora.toFormat('yyyyMMdd')}-${sufixo}`,
    data_abertura: agora.toFormat('dd/MM/yyyy HH:mm'),
  },
};

