// Recebe a saída da IA (caminho de sucesso) ou o erro (caminho de falha) e aplica o fallback quando necessário.
const base = $('Validar e Normalizar').first().json;
const out = $json.output || {};
const CATEGORIAS = ['Acadêmico', 'Técnico', 'Financeiro', 'Outro', 'Revisão manual'];
const URGENCIAS = ['Baixa', 'Média', 'Alta'];

const iaOk = !$json.error
  && CATEGORIAS.includes(out.categoria)
  && URGENCIAS.includes(out.urgencia)
  && typeof out.resposta === 'string' && out.resposta.trim().length > 0;

const triagem = iaOk
  ? {
      categoria: out.categoria,
      urgencia: out.urgencia,
      resumo: String(out.resumo || base.duvida.slice(0, 100)).trim().slice(0, 200),
      resposta_ia: out.resposta.trim().slice(0, 800),
      classificado_por_ia: true,
    }
  : {
      categoria: 'Revisão manual',
      urgencia: 'Média',
      resumo: base.duvida.slice(0, 100),
      resposta_ia: 'Recebemos sua dúvida. A equipe da disciplina vai analisá-la e responder em breve.',
      classificado_por_ia: false,
    };

const status = (triagem.categoria === 'Revisão manual' || !triagem.classificado_por_ia) ? 'Em revisão' : 'Respondida';

return [{
  json: {
    protocolo: base.protocolo,
    data_abertura: base.data_abertura,
    nome: base.nome,
    email: base.email,
    curso: base.curso,
    duvida: base.duvida,
    ...triagem,
    status,
    precisa_equipe: triagem.urgencia === 'Alta' || status === 'Em revisão',
  },
}];

